import{_ as o,o as t,c as a,a2 as l}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"O10 导入功能全量审计","description":"","frontmatter":{},"headers":[],"relativePath":"audit/O10-import.md","filePath":"audit/O10-import.md","lastUpdated":1792449669000}'),i={name:"audit/O10-import.md"};function d(r,e,c,n,s,h){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="o10-导入功能全量审计" tabindex="-1">O10 导入功能全量审计 <a class="header-anchor" href="#o10-导入功能全量审计" aria-label="Permalink to &quot;O10 导入功能全量审计&quot;">​</a></h1><ul><li>审计域：导入节点（分享链接 / 订阅内容 / 订阅源 URL / 批量导入 / 去重 / SSRF / 连通性检测）</li><li>对照手册：<code>doc/guide/import.md</code></li><li>结论：<strong>P0 0 / P1 0 / P2 3 / P3 6</strong></li><li>只审计未修复。</li></ul><h2 id="p2" tabindex="-1">P2 <a class="header-anchor" href="#p2" aria-label="Permalink to &quot;P2&quot;">​</a></h2><h3 id="imp-002-手册与代码不符-订阅抓取-ua-不是-mihomo" tabindex="-1">IMP-002 手册与代码不符：订阅抓取 UA 不是 Mihomo <a class="header-anchor" href="#imp-002-手册与代码不符-订阅抓取-ua-不是-mihomo" aria-label="Permalink to &quot;IMP-002 手册与代码不符：订阅抓取 UA 不是 Mihomo&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/secure_fetch.go:254</code>、<code>go-backend/internal/http/handler/kernel_external.go:229</code></li><li>手册称：&quot;面板服务器会以 Mihomo 的身份去下载，拿到的通常是参数最完整的 Clash 配置&quot;。</li><li>实际代码：<code>req.Header.Set(&quot;User-Agent&quot;, &quot;flvx-panel/1.0&quot;)</code>。<code>kernel_external.go:229</code> 的注释 &quot;The Mihomo user agent makes most providers return a Clash profile&quot; 已过时，代码并不发送 Mihomo UA。</li><li>影响：依赖 UA 嗅探的订阅源可能返回参数不完整的内容（例如只给 base64 而不给 Clash）。<code>ParseImport</code> 能解析多种格式，影响有限，但手册承诺与实现不一致。</li><li>复现：任意订阅源抓包观察 User-Agent。</li></ul><h3 id="imp-003-订阅源的-relayonly-修改不同步到已有节点" tabindex="-1">IMP-003 订阅源的 RelayOnly 修改不同步到已有节点 <a class="header-anchor" href="#imp-003-订阅源的-relayonly-修改不同步到已有节点" aria-label="Permalink to &quot;IMP-003 订阅源的 RelayOnly 修改不同步到已有节点&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/remote_source.go</code>（<code>syncRemoteSource</code> 更新分支）</li><li>更新分支只写 <code>Name/Protocol/Listen/Port/ShareHost/Extra/UpdatedTime</code>，从不写 <code>row.RelayOnly</code>：<div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">row.Name, row.Protocol, row.Listen, row.Port </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fresh.Name, fresh.Protocol, fresh.Listen, fresh.Port</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">row.ShareHost, row.Extra, row.UpdatedTime </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fresh.ShareHost, fresh.Extra, now</span></span></code></pre></div><code>fresh.RelayOnly</code>（来自 <code>src.RelayOnly</code>）被丢弃。</li><li>更严重：<code>remoteSourceSave</code> 中 URL 未变时 <code>fetch=false</code>，直接返回不同步，RelayOnly/IntervalHours 的修改当时完全不落地到节点。</li><li>影响：用户在订阅源上勾选&quot;订阅里只保留中转线路&quot;后，已有节点保持旧值，订阅行为与界面显示不一致。需删除重建订阅源才能生效。</li><li>复现：建订阅源（RelayOnly=关）→ 同步出节点 → 编辑订阅源改 RelayOnly=开（URL 不变）→ 节点 RelayOnly 仍为 0。</li></ul><h3 id="imp-004-编辑导入节点可绕过去重-产生重复-host-port" tabindex="-1">IMP-004 编辑导入节点可绕过去重，产生重复 host:port <a class="header-anchor" href="#imp-004-编辑导入节点可绕过去重-产生重复-host-port" aria-label="Permalink to &quot;IMP-004 编辑导入节点可绕过去重，产生重复 host:port&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/kernel_external.go</code>（<code>inboundExternalUpdate</code>）</li><li><code>inboundImport</code> 建节点时用 <code>seen[externalKey(host,port)]</code> 去重（手册：&quot;同一个地址和端口不会重复导入&quot;），但 <code>inboundExternalUpdate</code> 修改地址后没有任何去重检查。</li><li>复现：导入 A（1.1.1.1:8388）、B（2.2.2.2:8388）→ 编辑 B 的地址为 1.1.1.1:8388 → 成功，库里出现两个同地址节点。</li><li>影响：订阅渲染出现重复节点；与手册去重承诺矛盾。</li></ul><h2 id="p3" tabindex="-1">P3 <a class="header-anchor" href="#p3" aria-label="Permalink to &quot;P3&quot;">​</a></h2><h3 id="imp-005-validatesubscriptionurl-已是死代码" tabindex="-1">IMP-005 <code>validateSubscriptionURL</code> 已是死代码 <a class="header-anchor" href="#imp-005-validatesubscriptionurl-已是死代码" aria-label="Permalink to &quot;IMP-005 `validateSubscriptionURL` 已是死代码&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/kernel_external.go:63</code></li><li>该函数（旧 H-15 实现）除测试文件 <code>kernel_external_h15_test.go</code> 外无任何生产调用；实际抓取走 <code>SecureFetch</code>。留存易误导后人以为有两套校验。</li></ul><h3 id="imp-006-http-订阅源地址-保存成功、同步必败" tabindex="-1">IMP-006 http 订阅源地址&quot;保存成功、同步必败&quot; <a class="header-anchor" href="#imp-006-http-订阅源地址-保存成功、同步必败" aria-label="Permalink to &quot;IMP-006 http 订阅源地址&quot;保存成功、同步必败&quot;&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/remote_source.go:262</code>（<code>remoteSourceSave</code>）</li><li><code>isSubscriptionURL</code> 接受 <code>http://</code>，保存成功；但 <code>SecureFetch</code> 对公网 http 在任何配置下都拒绝（手册亦写明）。用户得到&quot;保存成功&quot;后看到同步失败 <code>public http not allowed</code>，体验割裂。应在保存时即提示必须 https（或给出明确文案）。</li></ul><h3 id="imp-007-公网-http-拒绝信息为英文" tabindex="-1">IMP-007 公网 http 拒绝信息为英文 <a class="header-anchor" href="#imp-007-公网-http-拒绝信息为英文" aria-label="Permalink to &quot;IMP-007 公网 http 拒绝信息为英文&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/secure_fetch.go</code>（<code>validateFetchIP</code>）</li><li>中文 UI 下返回 <code>public http not allowed (use https)</code>，与其他中文错误文案不一致。</li></ul><h3 id="imp-008-单次-500-上限未在手册说明-且两处行为不一致" tabindex="-1">IMP-008 单次 500 上限未在手册说明，且两处行为不一致 <a class="header-anchor" href="#imp-008-单次-500-上限未在手册说明-且两处行为不一致" aria-label="Permalink to &quot;IMP-008 单次 500 上限未在手册说明，且两处行为不一致&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/kernel_external.go:27</code>（<code>maxImportNodes = 500</code>）</li><li>手动导入超 500 直接拒绝（&quot;一次最多导入 500 个节点&quot;）；订阅源同步超 500 静默截断（记一条 Errors）。手册两处均未提及。</li></ul><h3 id="imp-009-同步的名称匹配大小写敏感-主机名大小写抖动导致反复-已更新" tabindex="-1">IMP-009 同步的名称匹配大小写敏感，主机名大小写抖动导致反复&quot;已更新&quot; <a class="header-anchor" href="#imp-009-同步的名称匹配大小写敏感-主机名大小写抖动导致反复-已更新" aria-label="Permalink to &quot;IMP-009 同步的名称匹配大小写敏感，主机名大小写抖动导致反复&quot;已更新&quot;&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/remote_source.go</code>（<code>byName</code> / <code>sameImported</code>）</li><li><code>byName[row.Name]</code> 与 <code>sameImported</code> 均用原始大小写比较；<code>externalKey</code> 虽然 lower 了主机名，但 <code>sameImported</code> 比较的是 <code>row.Listen == node.Host</code>（未 lower）。服务商某次返回主机名大小写变化 → 每次同步都判为更新，重写行并触发 <code>retargetRelays</code> 检查。</li></ul><h3 id="imp-010-yaml-别名放大的理论风险-低" tabindex="-1">IMP-010 YAML 别名放大的理论风险（低） <a class="header-anchor" href="#imp-010-yaml-别名放大的理论风险-低" aria-label="Permalink to &quot;IMP-010 YAML 别名放大的理论风险（低）&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/kernel/proxy_parse.go</code>（<code>parseClashProfile</code>）</li><li><code>yaml.v3</code> 会展开锚个别名；精心构造的多级嵌套别名可放大内存。实测 9 级 doubling 锚点解析仅 0.3ms、无异常（别名解码共享引用，不指数爆炸的简单形状）。且导入接口仅管理员可调用（<code>/api/v1/inbound/*</code> 走 <code>requiresAdmin</code> 前缀），攻击者即管理员本人；请求体另有 10MB 上限。评 P3，仅建议保持现状并知晓。</li></ul><h2 id="已验证通过-附证据" tabindex="-1">已验证通过（附证据） <a class="header-anchor" href="#已验证通过-附证据" aria-label="Permalink to &quot;已验证通过（附证据）&quot;">​</a></h2><ol><li><strong>分享链接边界</strong>（实测，<code>TestProbeImportEdges</code> 临时测试，已清理）： <ul><li><code>ss://...@127.0.0.1:8388</code> → &quot;第 1 行：地址不能是本机或 0.0.0.0&quot;（<code>proxy_parse.go</code> → <code>ValidateImportHost</code>，<code>import.go:27</code>）</li><li><code>vmess://not-base64!!!</code> → &quot;第 1 行：vmess 链接格式不正确（只支持 v2rayN 格式）&quot;</li><li>无名节点 → 默认名为 <code>host:port</code>（<code>finishProxy</code>）</li><li><code>wg://</code> / <code>ssr://</code> → &quot;第 1 行：暂不支持 wg:// 链接&quot;，与手册&quot;暂不支持 WireGuard、SSR…逐条提示&quot;一致</li></ul></li><li><strong>去重</strong>：<code>inboundImport</code> 用 <code>externalKey</code>（<code>net.JoinHostPort(strings.ToLower(host), port)</code>）建 <code>seen</code>，同地址端口不重复导入，批内重复同样拦截；与手册一致（<code>kernel_external.go:140-146,170-176</code>）。</li><li><strong>SSRF</strong>：订阅抓取统一走 <code>SecureFetch</code>（<code>fetchSubscriptionInfo</code>）：scheme 白名单 → 元数据硬黑名单（含 IPv4-mapped 展开）→ 逐 IP 判定（私网需 <code>FLVX_FETCH_ALLOW_PRIVATE_NETWORKS</code> / <code>FLVX_FETCH_PRIVATE_ALLOWLIST</code>）→ 公网强制 https → 拨号时重解析防 DNS rebinding → 重定向逐跳重校验（<code>secure_fetch.go</code> 全文件）；与手册&quot;订阅源地址安全策略&quot;节一致。</li><li><strong>连通性检测</strong>：<code>externalProbeInterval = 3 * time.Minute</code>（<code>kernel_probe.go:20</code>），与手册&quot;每 3 分钟&quot;一致；<code>externalProbeSkipped</code> 对 hysteria2/tuic 跳过（<code>kernel_probe.go:121</code>），与手册&quot;Hysteria2、TUIC…不显示状态&quot;一致。</li><li><strong>订阅源同步</strong>：按名称优先、地址兜底匹配（<code>syncRemoteSource</code>）；节点地址/参数变更后调 <code>retargetRelays</code> + <code>applyChainReferrers</code>，中转自动指向新地址，与手册一致；删源时有中转/被链式引用的节点保留（Kept），与&quot;删除只会删除面板里的记录和相关中转&quot;基本一致。</li><li><strong>鉴权</strong>：<code>/api/v1/inbound/import</code>、<code>/api/v1/subscription/source/*</code> 均在 <code>/api/v1/inbound/</code>、<code>/api/v1/subscription/</code> 前缀下，受 <code>requiresAdmin</code> 保护（J 域已交叉验证）。</li><li><strong>DoS 上限</strong>：<code>decodeJSON</code> 请求体 10MB（<code>handler.go:1594</code>）；订阅体 5MB（<code>kernel_external.go:30,247</code>）；<code>SecureFetch</code> 50MB（外层先被 5MB 拦截）。</li><li><strong>无 XXE</strong>：解析仅涉及 JSON / YAML / base64 / URL，无 XML 解析。</li></ol><h2 id="未能验证" tabindex="-1">未能验证 <a class="header-anchor" href="#未能验证" aria-label="Permalink to &quot;未能验证&quot;">​</a></h2><ul><li>真实订阅源端到端抓取（含重定向、私网 allowlist 生效）——无可用的外部订阅 URL 及受控 DNS，沙箱 DNS 被拦截；</li><li>前端导入页交互（粘贴/定时同步开关/错误展示）——无浏览器环境。</li></ul>',26)])])}const m=o(i,[["render",d]]);export{p as __pageData,m as default};
